import{_ as e,c as r,o as s,ag as i}from"./chunks/framework.B-XtCDNB.js";const p=JSON.parse('{"title":"Multi-Store Setup","description":"","frontmatter":{"subtitle":"Run multiple storefronts from a single installation."},"headers":[],"relativePath":"merchant/settings/multi-store.md","filePath":"merchant/settings/multi-store.md"}'),a={name:"merchant/settings/multi-store.md"};function o(n,t,d,c,l,h){return s(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="multi-store-setup" tabindex="-1">Multi-Store Setup <a class="header-anchor" href="#multi-store-setup" aria-label="Permalink to &quot;Multi-Store Setup&quot;">​</a></h1><p>Meloncart supports running multiple storefronts from a single October CMS installation using the <a href="https://docs.octobercms.com/4.x/cms/features/multisite.html" target="_blank" rel="noreferrer">Multisite</a> feature. Each store can have its own products, categories, pricing rules, orders, and settings while sharing the same backend and codebase.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>October CMS organizes sites into <strong>site groups</strong>. A site group represents a single store, and each group can contain multiple sites: one per language or locale. For example:</p><table tabindex="0"><thead><tr><th>Site Group</th><th>Sites</th></tr></thead><tbody><tr><td>US Store</td><td>English (primary)</td></tr><tr><td>EU Store</td><td>English, French, German</td></tr><tr><td>JP Store</td><td>Japanese</td></tr></tbody></table><p>Meloncart scopes all shop data by site group. When you create a product in the US Store, it only appears in the US Store. The EU Store has its own separate product catalog, categories, orders, and settings. Within a site group, content is shared across all locale sites and can be translated.</p><h3 id="site-groups-vs-sites" tabindex="-1">Site Groups vs Sites <a class="header-anchor" href="#site-groups-vs-sites" aria-label="Permalink to &quot;Site Groups vs Sites&quot;">​</a></h3><p>It is important to understand the distinction:</p><ul><li><strong>Site Group</strong> = A store. Products, orders, categories, and settings belong to a site group.</li><li><strong>Site</strong> = A locale within a store. A French site and an English site within the same group share the same products, but product names and descriptions can be translated into each language.</li></ul><h2 id="setting-up-multiple-stores" tabindex="-1">Setting Up Multiple Stores <a class="header-anchor" href="#setting-up-multiple-stores" aria-label="Permalink to &quot;Setting Up Multiple Stores&quot;">​</a></h2><h3 id="_1-create-site-groups" tabindex="-1">1. Create Site Groups <a class="header-anchor" href="#_1-create-site-groups" aria-label="Permalink to &quot;1. Create Site Groups&quot;">​</a></h3><p>Navigate to <strong>Settings → Manage Sites</strong> in the backend. Create a site group for each store you want to operate. Within each group, create one or more sites for the languages you want to support.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Your primary site must belong to a site group. If you are adding multi-store support to an existing installation, create a site group and assign your existing primary site to it.</p></div><h3 id="_2-configure-store-settings" tabindex="-1">2. Configure Store Settings <a class="header-anchor" href="#_2-configure-store-settings" aria-label="Permalink to &quot;2. Configure Store Settings&quot;">​</a></h3><p>Each store has its own independent settings. After switching to a store&#39;s site in the backend (using the site picker in the top navigation), configure the following under <strong>Settings</strong>:</p><ul><li><strong>eCommerce Settings</strong>: Tax display preferences and default location for each store</li><li><strong>Shipping &amp; Measurements</strong>: Weight and dimension units, shipping origin address</li><li><strong>Company Information</strong>: Company name and contact details for invoices</li><li><strong>Review Settings</strong>: Review moderation policies</li></ul><p>Settings are scoped per store, so your US Store can use pounds and inches while your EU Store uses kilograms and centimeters.</p><h3 id="_3-create-store-content" tabindex="-1">3. Create Store Content <a class="header-anchor" href="#_3-create-store-content" aria-label="Permalink to &quot;3. Create Store Content&quot;">​</a></h3><p>With your target store selected in the site picker, create products, categories, manufacturers, and other catalog content. All records created while a store is active are automatically assigned to that store.</p><p>The following data is scoped per store:</p><table tabindex="0"><thead><tr><th>Data</th><th>Per Store</th><th>Translatable</th></tr></thead><tbody><tr><td>Products</td><td>Yes</td><td>Name, slug, title, descriptions</td></tr><tr><td>Categories</td><td>Yes</td><td>Name, slug, title, descriptions</td></tr><tr><td>Manufacturers</td><td>Yes</td><td>Name, slug, description</td></tr><tr><td>Custom Groups</td><td>Yes</td><td>Name</td></tr><tr><td>Shipping Methods</td><td>Yes</td><td>Name, description</td></tr><tr><td>Cart Price Rules</td><td>Yes</td><td>Name, description</td></tr><tr><td>Catalog Price Rules</td><td>Yes</td><td>Name, description</td></tr><tr><td>Product Option Sets</td><td>Yes</td><td>Name</td></tr><tr><td>Product Extra Sets</td><td>Yes</td><td>Name</td></tr><tr><td>Product Property Sets</td><td>Yes</td><td>Name</td></tr><tr><td>Orders</td><td>Yes</td><td>:</td></tr><tr><td>Coupons</td><td>Yes</td><td>:</td></tr><tr><td>Reviews</td><td>Yes</td><td>:</td></tr></tbody></table><h3 id="_4-translate-content" tabindex="-1">4. Translate Content <a class="header-anchor" href="#_4-translate-content" aria-label="Permalink to &quot;4. Translate Content&quot;">​</a></h3><p>If a site group contains multiple locale sites, you can translate product names, descriptions, category names, and other text fields into each language. Switch to the target locale using the site picker, then edit the record to provide translated content.</p><p>Translatable fields are marked in the table above. Fields with slug translations also update the frontend URLs for that locale.</p><h2 id="storefront-routing" tabindex="-1">Storefront Routing <a class="header-anchor" href="#storefront-routing" aria-label="Permalink to &quot;Storefront Routing&quot;">​</a></h2><p>Each site can have its own domain or URL prefix. October CMS routes incoming requests to the correct site based on the hostname and URL, and Meloncart automatically loads the corresponding store&#39;s data.</p><p>For example:</p><table tabindex="0"><thead><tr><th>Site</th><th>URL</th></tr></thead><tbody><tr><td>US Store (English)</td><td><code>us.example.com</code></td></tr><tr><td>EU Store (English)</td><td><code>eu.example.com</code></td></tr><tr><td>EU Store (French)</td><td><code>eu.example.com/fr</code></td></tr></tbody></table><p>Your theme is shared across all sites. The same pages, partials, and layouts render content from whichever store the current request belongs to. No theme changes are needed to support multiple stores.</p><h2 id="backend-workflow" tabindex="-1">Backend Workflow <a class="header-anchor" href="#backend-workflow" aria-label="Permalink to &quot;Backend Workflow&quot;">​</a></h2><p>When working in the backend, the site picker in the top navigation controls which store you are managing. Switching sites changes the visible data throughout the backend:</p><ul><li>The product list shows only products from the selected store</li><li>The order list shows only orders from the selected store</li><li>Settings pages show the selected store&#39;s configuration</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Always verify which site is selected before creating or editing records. Records are assigned to the active store at the time of creation.</p></div><h2 id="shared-data" tabindex="-1">Shared Data <a class="header-anchor" href="#shared-data" aria-label="Permalink to &quot;Shared Data&quot;">​</a></h2><p>Some data is shared globally across all stores and is not scoped by site group:</p><ul><li><strong>Customers</strong>: User accounts are shared. A customer can place orders in any store.</li><li><strong>Tax Classes</strong>: Tax configuration is global and applies across stores.</li><li><strong>Order Statuses</strong>: Status definitions and transitions are shared.</li><li><strong>Payment Gateways</strong>: Payment method configuration is global.</li><li><strong>Product Types</strong>: Product type definitions are shared.</li><li><strong>Countries &amp; States</strong>: Location data is global.</li></ul><h2 id="multi-currency-pricing" tabindex="-1">Multi-Currency Pricing <a class="header-anchor" href="#multi-currency-pricing" aria-label="Permalink to &quot;Multi-Currency Pricing&quot;">​</a></h2><p>Meloncart supports displaying and managing prices in different currencies across your stores using the <a href="https://octobercms.com/plugin/responsiv-currency" target="_blank" rel="noreferrer">Currency</a> plugin. Each site can have its own display currency, and prices are automatically converted using exchange rates, or you can set fixed price overrides for specific currencies.</p><h3 id="currency-tiers" tabindex="-1">Currency Tiers <a class="header-anchor" href="#currency-tiers" aria-label="Permalink to &quot;Currency Tiers&quot;">​</a></h3><p>The currency system uses three tiers, each falling back to the one above it:</p><table tabindex="0"><thead><tr><th>Currency</th><th>Scope</th><th>Set In</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Default</strong></td><td>Global</td><td>Settings → Currencies</td><td>Anchor for all conversions; used when no other currency is configured</td></tr><tr><td><strong>Base</strong></td><td>Site Group</td><td>Settings → Site Groups</td><td>Stored currency for all sites in a group; defaults to the global default</td></tr><tr><td><strong>Site</strong></td><td>Site Definition</td><td>Settings → Site Definitions</td><td>Display currency for customers visiting that site; defaults to the base</td></tr></tbody></table><h3 id="setting-up-currencies" tabindex="-1">Setting Up Currencies <a class="header-anchor" href="#setting-up-currencies" aria-label="Permalink to &quot;Setting Up Currencies&quot;">​</a></h3><ol><li><p><strong>Create currencies</strong>: Navigate to <strong>Settings → Currencies</strong> and create the currencies your stores will use. Mark one as the <strong>Default</strong>.</p></li><li><p><strong>Configure exchange rates</strong>: Navigate to <strong>Settings → Exchange Rates</strong> and set up currency pairs. You can set fixed rates manually or use an automated provider (such as Fixer.io or FastForex) for real-time rates.</p></li><li><p><strong>Set a base currency per store</strong>: If your stores use different base currencies (e.g. US Store in USD, EU Store in EUR), navigate to <strong>Settings → Site Groups</strong> and select a <strong>Base Currency</strong> for each group. This step is optional: when left unset, the global default is used.</p></li><li><p><strong>Set a display currency per site</strong>: Navigate to <strong>Settings → Site Definitions</strong> and set the <strong>Currency</strong> for each site. This determines what currency customers see on the storefront.</p></li></ol><p>For example:</p><table tabindex="0"><thead><tr><th>Site</th><th>Locale</th><th>Currency</th></tr></thead><tbody><tr><td>US Store (English)</td><td><code>en</code></td><td>USD</td></tr><tr><td>EU Store (English)</td><td><code>en</code></td><td>EUR</td></tr><tr><td>EU Store (French)</td><td><code>fr</code></td><td>EUR</td></tr><tr><td>UK Store (English)</td><td><code>en</code></td><td>GBP</td></tr></tbody></table><h3 id="how-prices-work" tabindex="-1">How Prices Work <a class="header-anchor" href="#how-prices-work" aria-label="Permalink to &quot;How Prices Work&quot;">​</a></h3><p>Product prices are always stored in the store&#39;s base currency. When a customer visits a site with a different display currency, prices are automatically converted using exchange rates.</p><p>For example, if a product costs <strong>USD 100</strong> in the US Store and the USD → EUR exchange rate is 0.92, customers on the EU Store see <strong>EUR 92.00</strong> automatically.</p><h3 id="fixed-price-overrides" tabindex="-1">Fixed Price Overrides <a class="header-anchor" href="#fixed-price-overrides" aria-label="Permalink to &quot;Fixed Price Overrides&quot;">​</a></h3><p>Sometimes exchange-rate conversion is not ideal: you may want to set round numbers or market-specific prices. Meloncart supports fixed price overrides for any currency.</p><p>When editing a product on a non-base currency site, each price field shows the auto-converted value in a disabled input. Use the <strong>Override</strong> link to enter a fixed price for that currency. Use the <strong>Clear</strong> link to remove the override and revert to automatic conversion.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Fixed overrides are stored separately from the base price. Clearing an override does not affect the base price: it simply reverts to using the exchange rate.</p></div><h3 id="displaying-prices-on-the-storefront" tabindex="-1">Displaying Prices on the Storefront <a class="header-anchor" href="#displaying-prices-on-the-storefront" aria-label="Permalink to &quot;Displaying Prices on the Storefront&quot;">​</a></h3><p>Use the <code>currency</code> Twig filter with the <code>site</code> option to display prices in the visitor&#39;s currency:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ product.price</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">currency({ site: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) }}</span></span></code></pre></div><p>The current site&#39;s currency code is available as:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ this.site.currency_code }}</span></span></code></pre></div><h2 id="per-site-product-visibility" tabindex="-1">Per-Site Product Visibility <a class="header-anchor" href="#per-site-product-visibility" aria-label="Permalink to &quot;Per-Site Product Visibility&quot;">​</a></h2><p>Within a store, all sites share the same product catalog by default. However, you can control which products appear on which sites using per-site visibility.</p><p>To restrict a product to specific sites, edit the product and navigate to the <strong>Visibility</strong> tab. Check <strong>Limit Visibility to Specific Sites</strong>, then select the sites where the product should appear. Products with this setting unchecked remain visible on all sites in the store.</p><p>This works bidirectionally: you can hide products on the primary site while showing them on a regional site, or vice versa. For example, a store with English, French, and Colombian sites might show 12 products on the English site but 14 on the Colombian site.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Per-site visibility uses an opt-in model. When you add a new site to a store, restricted products will not appear on the new site until you explicitly add it to the product&#39;s visibility list.</p></div><h2 id="migrating-an-existing-store" tabindex="-1">Migrating an Existing Store <a class="header-anchor" href="#migrating-an-existing-store" aria-label="Permalink to &quot;Migrating an Existing Store&quot;">​</a></h2><p>If you have an existing single-store installation and want to add a second store:</p><ol><li>Create a site group under <strong>Settings → Manage Sites</strong> and assign your existing primary site to it.</li><li>Your existing data will be automatically associated with the primary site group.</li><li>Create a second site group for your new store and begin adding content to it.</li></ol>',65)])])}const g=e(a,[["render",o]]);export{p as __pageData,g as default};
